const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-110.517217, 45.506013);
  const buffer = point.buffer(3000); // 3km radius

  const date1_start = '2012-08-10';
  const date1_end = '2012-08-20';
  const date2_start = '2012-09-10';
  const date2_end = '2012-09-20';

  // 2. Data Acquisition & Preprocessing
  // Function to mask clouds from Landsat 7 SR data
  function maskL7srClouds(image) {
    var qa = image.select('pixel_qa');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    var cloudShadowBitMask = (1 << 3);
    var cloudsBitMask = (1 << 5);
    // Both flags should be set to zero, indicating clear conditions.
    var mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask).select(['B3', 'B4', 'B5', 'B7', 'sr_aerosol', 'pixel_qa']);
  }

  // Function to calculate NBR for Landsat 7 SR
  function calculateNBR_L7(image) {
    // NBR = (NIR - SWIR2) / (NIR + SWIR2)
    // Landsat 7 bands: B4 = NIR, B7 = SWIR2
    return image.normalizedDifference(['B4', 'B7']).rename('NBR');
  }

  // Get Landsat 7 SR collection for the region and time periods
  const l7 = ee.ImageCollection('LANDSAT/LE07/C01/T1_SR')
                 .filterBounds(buffer);

  // Process Period 1 (mid-August)
  let collection1 = l7.filterDate(date1_start, date1_end)
                      .map(maskL7srClouds)
                      .map(calculateNBR_L7);

  const size1 = await collection1.size().getInfo();
  if (size1 === 0) {
    console.log(`No images found for Period 1 (${date1_start} to ${date1_end}).`);
    console.log("C1");
    return;
  }
  const image1 = collection1.median();

  // Process Period 2 (mid-September)
  let collection2 = l7.filterDate(date2_start, date2_end)
                      .map(maskL7srClouds)
                      .map(calculateNBR_L7);

  const size2 = await collection2.size().getInfo();
  if (size2 === 0) {
    console.log(`No images found for Period 2 (${date2_start} to ${date2_end}).`);
    console.log("C1");
    return;
  }
  const image2 = collection2.median();

  // 3. Burn Scar Area Calculation
  // We'll use a simple NBR threshold for burn scar detection.
  // Lower NBR values indicate burned areas. A common threshold is around 0.1-0.2.
  // Let's use 0.1 for potentially severe burns, and consider pixels below this as 'burned'.
  const NBR_BURN_THRESHOLD = 0.1; // Adjust based on local conditions if known

  // Create burn scar masks for each period
  const burned_mask1 = image1.select('NBR').lt(NBR_BURN_THRESHOLD);
  const burned_mask2 = image2.select('NBR').lt(NBR_BURN_THRESHOLD);

  // Calculate the area of burned pixels
  const scale = 30; // Landsat resolution
  const pixelArea = ee.Image.pixelArea().updateMask(burned_mask1); // Area in m^2

  const area1_m2 = await pixelArea.mask(burned_mask1)
                                .reduceRegion({
                                  reducer: ee.Reducer.sum(),
                                  geometry: buffer,
                                  scale: scale,
                                  maxPixels: 1e9
                                }).get('area').getInfo();

  const area2_m2 = await pixelArea.mask(burned_mask2)
                                .reduceRegion({
                                  reducer: ee.Reducer.sum(),
                                  geometry: buffer,
                                  scale: scale,
                                  maxPixels: 1e9
                                }).get('area').getInfo();

  // Validate calculation results
  if (area1_m2 === null || area2_m2 === null || isNaN(area1_m2) || isNaN(area2_m2)) {
    console.log("Calculation of burn scar area failed.");
    console.log("C3");
    return;
  }

  // Convert to km^2 for readability
  const area1_km2 = area1_m2 / 1e6;
  const area2_km2 = area2_m2 / 1e6;

  // 4. Determine if the burn scar area increased
  const didIncrease = area2_km2 > area1_km2;

  console.log(`Period 1 Images: ${size1}`);
  console.log(`Period 2 Images: ${size2}`);
  console.log(`Burn scar area (mid-Aug 2012): ${area1_km2.toFixed(2)} km^2`);
  console.log(`Burn scar area (mid-Sep 2012): ${area2_km2.toFixed(2)} km^2`);

  // 5. Final Answer
  if (didIncrease) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (error) {
    console.error("Earth Engine authentication or initialization failed:", error);
    console.log("D"); // Indicate a D error for GEE setup issues
  }
}

initEE();
